import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. BUILD PLANE GEOMETRY & MATERIAL
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(2, 1.25, 1, 1);

  // Load image texture asynchronously and update material when ready
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.set(2.5, 1.6, 0);
  plane.rotation.set(0, 0, 0);
  plane.scale.set(1, 1, 1);

  // Load and apply texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.colorNode = texture;
    material.needsUpdate = true;
  });

  // ============================================================================
  // 2. INTERACTION STATE & CLEANUP TRACKING
  // ============================================================================
  const state = {
    isHovered: false,
    timelines: [],
  };

  // ============================================================================
  // 3. HOVER INTERACTION: RISE-IN EFFECT
  // ============================================================================
  const onPointerEnter = () => {
    if (state.isHovered) return;
    state.isHovered = true;

    // Kill any in-flight timeline
    state.timelines.forEach((tl) => tl.kill());
    state.timelines = [];

    // Preset: rise-in (y +0.15 -> 0, power3.out, 0.7s)
    const tl = gsap.timeline();
    tl.fromTo(
      plane.position,
      { y: plane.position.y + 0.15 },
      {
        y: plane.position.y,
        duration: 0.7,
        ease: 'power3.out',
      },
      0
    );
    state.timelines.push(tl);
  };

  const onPointerLeave = () => {
    state.isHovered = false;

    // Kill any in-flight timeline
    state.timelines.forEach((tl) => tl.kill());
    state.timelines = [];

    // Return to original y position
    const tl = gsap.timeline();
    tl.to(plane.position, {
      y: 1.6,
      duration: 0.5,
      ease: 'power2.out',
    });
    state.timelines.push(tl);
  };

  // ============================================================================
  // 4. CLICK INTERACTION: PRESS-DOWN + EMIT EVENT
  // ============================================================================
  const onPointerDown = () => {
    // Press-down: scale 0.97, 120ms, back.out
    state.timelines.forEach((tl) => tl.kill());
    state.timelines = [];

    const tl = gsap.timeline();
    tl.to(
      plane.scale,
      {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      },
      0
    );
    state.timelines.push(tl);
  };

  const onPointerUp = () => {
    // Release: scale back to 1.0
    state.timelines.forEach((tl) => tl.kill());
    state.timelines = [];

    const tl = gsap.timeline();
    tl.to(plane.scale, {
      x: 1,
      y: 1,
      duration: 0.3,
      ease: 'power2.out',
    });
    state.timelines.push(tl);

    // Emit navigation event
    ctx.emit('navigate', { to: 'hub-journal' });
  };

  // ============================================================================
  // 5. ATTACH EVENT HANDLERS TO userData
  // ============================================================================
  plane.userData.handlers = {
    onPointerEnter,
    onPointerLeave,
    onPointerDown,
    onPointerUp,
  };

  // ============================================================================
  // 6. CLEANUP FUNCTION
  // ============================================================================
  plane.userData.cleanup = () => {
    state.timelines.forEach((tl) => tl.kill());
    state.timelines = [];
    geometry.dispose();
    material.dispose();
  };

  return plane;
}
